
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_spbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_spbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.650909018907941e-02, -6.554864450718768e-02, -6.417554977282716e-02, -6.221794848734527e-02, -5.943879339660227e-02, -5.552028526616130e-02, -5.006316589803935e-02, -4.265476397650234e-02, -3.319590044620426e-02, -2.305832252075132e-02, -1.847623262305906e-02, -3.978822973598741e-02, -4.647169052906223e-02, -3.390990496660401e-02, -2.014473920838688e-02, -8.123175388902226e-03, -1.597876173649258e-03, -1.117069268845789e-04, -2.020216280000132e-06, -4.922828578273049e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


